extends SceneTree
## Temporary smoke test - run with: godot --headless --path . -s res://test_logic.gd

func _init() -> void:
	var fails := 0

	# --- Cooperation game: simulate a full 20-round playthrough ---
	var CooperateScript := load("res://scripts/cooperate.gd")
	var c = CooperateScript.new()
	root.add_child(c)  # triggers _ready, builds UI
	var give_pattern := [10, 10, 0, 5, 10, 10, 10, 0, 10, 5, 10, 10, 10, 10, 10, 0, 10, 10, 10, 10]
	for i in range(20):
		c._commit(give_pattern[i])
	if c.round_num != 20:
		push_error("FAIL: round_num=%d expected 20" % c.round_num); fails += 1
	if c.earnings["You"] <= 0.0 or c.earnings["Giver"] <= 0.0:
		push_error("FAIL: bad earnings"); fails += 1
	if not c.grudge_broken:
		push_error("FAIL: grudge should be broken after giving 0"); fails += 1
	var total: float = 0.0
	for name in c.earnings:
		total += c.earnings[name]
	if total < 200.0:
		push_error("FAIL: community total too low: %f" % total); fails += 1
	c._show_debrief()
	c._restart()
	if c.round_num != 0 or c.my_history.size() != 0:
		push_error("FAIL: restart did not reset"); fails += 1
	c.free()

	# --- Aid game: deploy every level at max-sensible allocation ---
	var AidScript := load("res://scripts/aid.gd")
	var a = AidScript.new()
	root.add_child(a)
	var budgets := [500, 2000, 5000, 3000, 10000]
	for lv in range(5):
		if a.level_index != lv:
			push_error("FAIL: level_index=%d expected %d" % [a.level_index, lv]); fails += 1
		var data: Dictionary = a.levels[lv]
		if data["budget"] != budgets[lv]:
			push_error("FAIL: budget mismatch level %d" % lv); fails += 1
		# spend exactly the budget on the first affordable options
		var left: int = data["budget"]
		for opt in data["options"]:
			var sb: SpinBox = a.spinboxes[opt["name"]]
			var units: int = mini(int(left / opt["cost"]), 10000)
			sb.value = units
			left -= units * opt["cost"]
		a._on_deploy()
		if not a.deployed:
			push_error("FAIL: deploy rejected at level %d (left=%d)" % [lv, left]); fails += 1
		a._on_next()
	a._show_report()
	if a.total_spent != 500 + 2000 + 5000 + 3000 + 10000:
		push_error("FAIL: total_spent=%d" % a.total_spent); fails += 1
	if a.total_helped <= 0.0:
		push_error("FAIL: nobody helped?"); fails += 1
	a.free()

	if fails == 0:
		print("ALL SMOKE TESTS PASSED (cooperation playthrough, aid 5-level playthrough)")
	else:
		print("%d FAILURES" % fails)
	quit(0 if fails == 0 else 1)

